 OR EXISTS(SELECT 1 FROM vec_dietas.version_tarifa_registrada WHERE version_ref='tarifa:dipgra:2026:art30:v1')
 THEN RAISE EXCEPTION 'Dietas: catálogo ausente o versión ya publicada' USING ERRCODE='55000'; END IF;
