INSERT INTO vec_dietas.catalogo_liquidacion_publicado
(referencia,version,huella_sha256,catalogo_canonico,catalogo,publicacion_ref,fecha_publicacion,normas,
 vigente_desde,vigente_hasta,version_tarifa_ref,pais_iso2,grupo,vehiculo,regla_ref,regla_huella_sha256,registrada_en)
SELECT v->>'referencia',v->>'version',v->>'huella_sha256',canonico,v,v->>'publicacion_ref',
 (v->>'fecha_publicacion')::date,v->'normas',(v->>'vigente_desde')::date,(v->>'vigente_hasta')::date,
 v->>'version_tarifa_ref',v->>'pais_iso2',(v->>'grupo')::smallint,v->>'vehiculo',
 v->'regla_devengo'->>'referencia',v->'regla_devengo'->>'huella_sha256',clock_timestamp() FROM leidos;
INSERT INTO vec_dietas.version_tarifa_registrada(version_ref,origen,catalogo_ref,catalogo_version,catalogo_sha256)
SELECT version_tarifa_ref,'publicada',referencia,version,huella_sha256
FROM vec_dietas.catalogo_liquidacion_publicado
WHERE referencia='catalogo:dipgra:2026:grupo1:propio' AND version='version:2026-10-05:v1';
INSERT INTO vec_dietas.regla_devengo_registrada(regla_ref,version_ref,origen,huella_sha256,catalogo_ref,catalogo_version,catalogo_sha256)
SELECT regla_ref,version_tarifa_ref,'publicada',regla_huella_sha256,referencia,version,huella_sha256
FROM vec_dietas.catalogo_liquidacion_publicado
WHERE referencia='catalogo:dipgra:2026:grupo1:propio' AND version='version:2026-10-05:v1';
DO $post$ BEGIN
 IF (SELECT count(*) FROM vec_dietas.catalogo_liquidacion_publicado WHERE version_tarifa_ref='tarifa:dipgra:2026:art30:v1')<>6
 THEN RAISE EXCEPTION 'Dietas: publicación incompleta' USING ERRCODE='55000'; END IF;
END $post$;
COMMIT;
